{
  "items": [
    {
      "name": "ENNReal.nhds_zero_basis_Iic",
      "module_name": "Mathlib.Topology.Instances.ENNReal.Lemmas",
      "kind": "theorem",
      "type": "(nhds 0).HasBasis (fun a => 0 < a) Set.Iic"
    },
    {
      "name": "WithZeroTopology.hasBasis_nhds_zero",
      "module_name": "Mathlib.Topology.Algebra.WithZeroTopology",
      "kind": "theorem",
      "type": "∀ {Γ₀ : Type u_2} [inst : LinearOrderedCommGroupWithZero Γ₀], (nhds 0).HasBasis (fun γ => γ ≠ 0) Set.Iio"
    },
    {
      "name": "exists_Icc_mem_subset_of_mem_nhdsGE",
      "module_name": "Mathlib.Topology.Order.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [OrderTopology α] {a : α} {s : Set α},\n  s ∈ nhdsWithin a (Set.Ici a) → ∃ b, a ≤ b ∧ Set.Icc a b ∈ nhdsWithin a (Set.Ici a) ∧ Set.Icc a b ⊆ s"
    },
    {
      "name": "ENNReal.nhds_zero_basis",
      "module_name": "Mathlib.Topology.Instances.ENNReal.Lemmas",
      "kind": "theorem",
      "type": "(nhds 0).HasBasis (fun a => 0 < a) fun a => Set.Iio a"
    },
    {
      "name": "NNReal.nhds_zero_basis",
      "module_name": "Mathlib.Topology.Instances.NNReal.Lemmas",
      "kind": "theorem",
      "type": "(nhds 0).HasBasis (fun a => 0 < a) fun a => Set.Iio a"
    },
    {
      "name": "ENNReal.hasBasis_nhds_of_ne_top",
      "module_name": "Mathlib.Topology.Instances.ENNReal.Lemmas",
      "kind": "theorem",
      "type": "∀ {x : ENNReal}, x ≠ ⊤ → (nhds x).HasBasis (fun x => 0 < x) fun ε => Set.Icc (x - ε) (x + ε)"
    }
  ]
}
